// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address recipient, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        if (amount > 0) {
            vm.deal(address(this), amount);
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent);
        }

        bool ok;
        address beforeOwner = c.owner();
        require(beforeOwner == address(this));

        vm.prank(address(this));
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.owner() == beforeOwner);
        } else {
            assertTrue(c.owner() == beforeOwner);
        }
    }
}
